<script setup>
import {preservesLocks,openingSlot} from '../planner/feasibility';
import {collectPlanningRoutes,collectAlternativeRoutes} from '../services/planningTransport';
import {routeKey} from '../planner/travel';
import {nearbyRouteCandidates} from '../planner/routeCandidates';
import {discoverAlongRoute} from '../services/routeDiscovery';
import {evaluatePlan} from '../planner/planQuality';
import {visitProfile,parentProfile,containedBy} from '../planner/visitDuration';
import PlacePicker from '../components/PlacePicker.vue';
import FavoriteButton from '../components/FavoriteButton.vue';
import {saveHistory} from '../services/travelLibrary';
import {samePlace} from '../planner/identity';
import {computed,ref,watch,onBeforeUnmount,onMounted} from 'vue';
import {t,language} from '../i18n';
import {generateItineraries,scheduleDay,fillDay,clock,mealWindows,preferenceScore} from '../planner/planner';
import JourneyCover from '../components/JourneyCover.vue';
import {forecastForDate,weatherKind} from '../services/weatherService';
import UnifiedTripMap from '../components/UnifiedTripMap.vue';
import TripTransport from '../components/TripTransport.vue';
import {placeName} from '../utils/globalLabels';
import {loadPlacePresentation,safeWebsite} from '../services/placePresentation';
import WeatherAdvice from '../components/WeatherAdvice.vue';
import {assessWeather} from '../planner/weatherOptimizer';
import WeatherPanel from '../components/WeatherPanel.vue';
import PlaceDescription from '../components/PlaceDescription.vue';
import ActivityImage from '../components/ActivityImage.vue';
import TouristReviews from '../components/TouristReviews.vue';
const props=defineProps({restored:Object,settings:Object,destination:Object,places:Array,limited:Boolean,pending:Array,dataWarnings:{type:Array,default:()=>[]}});
const emit=defineEmits(['back','snapshot']);
const archiveMode=ref(Boolean(props.restored)),storageMessage=ref(''),showHotelPicker=ref(false),routeId=ref(props.restored?.routeId||crypto.randomUUID());
const routeCandidates=ref([]);
const eligible=computed(()=>[...new Map([...props.places,...routeCandidates.value].map(p=>[p.id,p])).values()]);
const settings=ref({...props.settings,mustIds:[...(props.settings.mustIds||[])]});
const variants=ref(props.restored?[structuredClone(JSON.parse(JSON.stringify(props.restored.plan)))]:generateItineraries(eligible.value,settings.value)),pace=ref(props.restored?.plan.id||props.settings.pace),dayIndex=ref(0),active=ref(''),history=ref([]),notice=ref(''),comparison=ref(false);
const routePaths=ref([]);
const photoEvents=computed(()=>day.value.events.filter(e=>e.place&&e.kind!=='HOTEL'));
const weatherSummary=computed(()=>current.value.days.map(d=>forecastForDate(weatherState.value.data,d.date)).filter(Boolean));
const travelTitle=computed(()=>language.value==='zh'?`${displayName.value}，${settings.value.days===3?'三':settings.value.days}日漫游。`:`${displayName.value}, ${settings.value.days} days to explore.`);
function scrollToJourney(){document.getElementById('journey-route')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
function transportLabel(event){return event.travel?.estimated?(language.value==='zh'?'估算':'estimated'):(language.value==='zh'?'高德查询':'AMap');}
function orderOf(event){return mapPlaces.value.find(p=>p.id===event.place?.id)?.sequence||'';}

watch([pace,dayIndex],()=>routePaths.value=[]);
watch(pace,(next,previous)=>{if(!Object.keys(settings.value.lockedSlots||{}).length)return;const original=variants.value.find(p=>p.id===previous);const preservedDays=Object.fromEntries(original.days.filter(d=>d.events.some(e=>Boolean(settings.value.lockedSlots?.[e.id]))).map(d=>[d.date,d]));const rebuilt=generateItineraries(eligible.value,{...settings.value,preservedDays}).find(p=>p.id===next);variants.value=variants.value.map(p=>p.id===next?rebuilt:p);});
const current=computed(()=>variants.value.find(p=>p.id===pace.value));
const day=computed(()=>current.value.days[dayIndex.value]);
const quality=computed(()=>evaluatePlan(current.value,settings.value));
const weatherState=ref({status:settings.value.weather?'ready':'loading',data:settings.value.weather||null});
watch(()=>weatherState.value.data,data=>{if(data)settings.value={...settings.value,weather:data};});
const validationMessage=ref(''),editFeedback=ref(''),editTarget=ref(''),transportLoading=ref(false);let transportVersion=0;
function rescheduleDay(d){
 let items=[...d.items];const otherMeals=current.value.days.filter(other=>other!==d).flatMap(other=>other.events.filter(e=>e.kind==='MEAL'&&e.place).map(e=>e.place));const food=eligible.value.filter(p=>p.category==='FOOD'&&!otherMeals.some(q=>samePlace(p,q)));let mealCandidates=food;const run=()=>scheduleDay(items,{...settings.value,planningDate:d.date,assignedMeals:d.mealAssignments},pace.value,mealCandidates);let next=run();const deferred=[];
 // Optional restaurant detours must not displace visits, especially manual edits.
 if(next.conflicts.length){mealCandidates=[];next=run();}
 while(next.conflicts.length&&!d.userEdited){const index=items.findLastIndex(i=>!settings.value.mustIds.includes(i.place.id)&&!settings.value.lockedSlots?.[i.place.id]);if(index<0)break;deferred.push(items[index].place.name);items.splice(index,1);next=run();}
 if(!d.userEdited&&(deferred.length||!d.transportReviewed)){
 d.transportReviewed=true;
 const taken=current.value.days.filter(other=>other!==d).flatMap(other=>other.events.filter(e=>e.place).map(e=>e.place));
 const rejected=new Set([...(d.transportRejected||[]),...d.items.filter(i=>!items.includes(i)).map(i=>i.place.id)]);
 d.transportRejected=[...rejected];
 next=fillDay({...d,...next},eligible.value.filter(p=>!taken.some(q=>samePlace(p,q)||containedBy(p,q)||containedBy(q,p))&&!rejected.has(p.id)&&!eligible.value.some(q=>q!==p&&containedBy(p,q))),settings.value,pace.value,food);
 }
 if(deferred.length)editFeedback.value=(language.value==='zh'?'真实交通更新后时间不足，已暂不安排推荐景点：':'After route updates, optional stops no longer fit: ')+deferred.join(' / ');
 return {...d,...next,underfilled:next.items.length<2&&!next.items.some(i=>i.place.visit?.fullDay),conflictOrigin:'transport'};
}
function syncTrafficPaths(){const points=[settings.value.origin,...day.value.events.filter(e=>e.place).map(e=>e.place)].filter(Boolean);routePaths.value=points.slice(1).flatMap((p,i)=>settings.value.routes?.[routeKey(points[i],p,settings.value.transport||'transit')]?.segments||[]).filter(s=>s.path?.length>=2);}
async function refreshTransport(){
 if(archiveMode.value)return;
 const token=++transportVersion;transportLoading.value=true;const target=day.value;
 const isCurrent=()=>token===transportVersion&&!disposed;
 try{
  if(!target.discoveryReviewed){
   const extra=await discoverAlongRoute(target,props.destination,isCurrent);if(!isCurrent())return;
   routeCandidates.value=[...new Map([...routeCandidates.value,...extra].map(p=>[p.id,p])).values()];
   target.discoveryReviewed=true;
  }
  let routes=await collectPlanningRoutes(target,props.destination,settings.value,isCurrent);
  if(!isCurrent())return;
  if(!target.transportReviewed){
   const taken=new Set(current.value.days.filter(d=>d!==target).flatMap(d=>d.events.filter(e=>e.place).map(e=>e.place.id)));
   const routeSettings={...settings.value,pace:pace.value,routes:{...settings.value.routes,...routes}};
   const preview=scheduleDay(target.items,{...routeSettings,planningDate:target.date,assignedMeals:target.mealAssignments},pace.value,[]);
   const candidates=nearbyRouteCandidates({...target,...preview},eligible.value.filter(p=>!taken.has(p.id)),routeSettings);
   const extra=await collectAlternativeRoutes(target,candidates,props.destination,routeSettings,isCurrent);
   routes={...routes,...extra};
  }
  if(!isCurrent())return;
  if(Object.keys(routes).length||!target.transportReviewed){
   settings.value={...settings.value,routes:{...settings.value.routes,...routes}};
   Object.assign(target,rescheduleDay(target));validationMessage.value='';
   // Verify newly inserted restaurants/stops once. Failures retain explicit estimates.
   const verified=await collectPlanningRoutes(target,props.destination,settings.value,isCurrent);
   if(!isCurrent())return;
   if(Object.keys(verified).length){settings.value={...settings.value,routes:{...settings.value.routes,...verified}};Object.assign(target,rescheduleDay(target));}
  }
  // Do not recursively regenerate all variants when a real route remains infeasible.
  // Keep the exact conflict visible, with the existing explicit regenerate action.
  syncTrafficPaths();
 }catch{
  if(isCurrent())editFeedback.value=language.value==='zh'?'部分交通暂未核实，未取得的路段保留估算。':'Some journeys could not be verified; unavailable legs remain estimates.';
 }finally{if(isCurrent())transportLoading.value=false;}
}
function acceptTransport(legs){if(!legs.length)return;const mode=legs[0].requestedMode||settings.value.transport||'transit';settings.value={...settings.value,transport:mode};const routes={...settings.value.routes};for(const l of legs){const r=l.options?.[l.chosen||0];if(r)routes[routeKey(l.from,l.to,settings.value.transport||'transit')]={...r,fetchedAt:Date.now()};}settings.value={...settings.value,routes};Object.assign(day.value,rescheduleDay(day.value));validationMessage.value='';syncTrafficPaths();}

const weatherAssessment=computed(()=>assessWeather(current.value,weatherState.value.data));
function eventRisk(event){return weatherAssessment.value.risks[day.value.date+'|'+event.id];}
function applyWeather(plan){snapshot();variants.value=variants.value.map(p=>p.id===pace.value?plan:p);routePaths.value=[];active.value='';notice.value='weatherAdvice.applied';}
const presentation=ref({});
const present=p=>p?{...p,...presentation.value[p.id]}:null;
const mapPlaces=computed(()=>{let n=0;return [...new Map(day.value.events.filter(e=>e.place).map(e=>[e.place.id,{...present(e.place),sequence:e.kind==='HOTEL'?'H':++n}])).values()];});
const transportPlaces=computed(()=>day.value.events.filter(e=>e.place).map(e=>present(e.place)));
let disposed=false,presentationBatch=0;
const jobs=new Set(),autoPhotoRetries=new Set();
function recoverPhoto(p){if(autoPhotoRetries.has(p.id))return;autoPhotoRetries.add(p.id);enrichDay(true,p.id,'photo');}
async function enrichDay(force=false,onlyId=null,onlyPart=null){
 const priority=++presentationBatch;

 const items=day.value.events.filter(e=>e.place&&e.kind!=='HOTEL'&&(!onlyId||e.place.id===onlyId)).map(e=>e.place);
 await Promise.all(items.flatMap(p=>(onlyPart?[onlyPart]:p.source==='amap'?(p.image||p.photos?.length?[]:['photo']):p.source==='opentripmap'?['text','photo']:['text','photo']).map(async part=>{
  const key=p.id+':'+part,status=part+'Status';
  if(part==='text'&&p.nameZh&&!force)return;
  if(jobs.has(key)||(!force&&presentation.value[p.id]?.[status]&&!(['error','missing'].includes(presentation.value[p.id][status])&&Date.now()-(presentation.value[p.id][status+'At']||0)>60000)))return;
  jobs.add(key);presentation.value[p.id]={...presentation.value[p.id],[status]:'loading'};
  try{
   const data=await loadPlacePresentation(present(p),props.destination.city,null,force,{part,priority});
   // 各通道仅更新自己的字段，慢图片响应不能覆盖已获得的译名。
   const fields=part==='photo'?['photo','photoStatus']:part==='text'?['translatedNameZh','nameTranslationSource','nameZh','nameZhSourceId','nameEnglish','descriptionZh','descriptionZhSource','website','description','descriptionLanguage']:['description','descriptionLanguage','website','sourceUrl'];
   const update=Object.fromEntries(fields.filter(k=>data[k]!=null).map(k=>[k,data[k]]));
   if(!disposed)presentation.value[p.id]={...presentation.value[p.id],...update,...(part==='photo'?{photoRevision:(presentation.value[p.id]?.photoRevision||0)+1}:{}),[status+'At']:Date.now(),[status]:data.status==='error'?'error':part==='photo'?(data.photoStatus||'missing'):'ready'};
  }catch{if(!disposed)presentation.value[p.id]={...presentation.value[p.id],[status]:'error',[status+'At']:Date.now()};}
  finally{jobs.delete(key);}
 })));
}
watch(()=>day.value.events.filter(e=>e.place).map(e=>e.place.id).join('|'),()=>enrichDay(),{immediate:true});
watch(()=>[pace.value,dayIndex.value,settings.value.transport,day.value.items.map(i=>i.place.id).join('|')].join(':'),()=>refreshTransport(),{immediate:true});
onBeforeUnmount(()=>{disposed=true;++transportVersion;});

const displayName=computed(()=>language.value==='zh'?props.destination.displayName:props.destination.canonicalName);
const missing=computed(()=>settings.value.interests.filter(i=>!props.places.some(p=>p.subcategories.includes(i))));
const nameFor=id=>props.places.find(p=>p.id===id)?.name||id;
function reason(event){
 if(event.kind==='HOTEL')return event.reason==='hotelDeparture'?(language.value==='zh'?'从住宿出发':'Depart accommodation'):(language.value==='zh'?'返回住宿':'Return to accommodation');
 if(event.reason==='interest')return t('planner.interestReason',{interests:event.matches.map(i=>t('planner.interests.'+i)).join(' / ')});
 return t('planner.'+({foodMeal:'foodReason',meal:'mealReason',rest:'restReason',must:'mustReason',nearby:'nearbyReason'}[event.reason]));
}
function title(event){if(event.kind==='MEAL'&&!event.place)return language.value==='zh'?(event.slot==='LUNCH'?'午餐 · 待选择餐厅':'晚餐 · 待选择餐厅'):(event.slot==='LUNCH'?'Lunch · restaurant to choose':'Dinner · restaurant to choose');if(event.kind==='HOTEL')return (event.reason==='hotelDeparture'?(language.value==='zh'?'出发 · ':'Depart · '):(language.value==='zh'?'返回 · ':'Return · '))+event.place.name;const p=event.place&&present(event.place);return (p?(language.value==='zh'&&!p.nameZh&&p.translatedNameZh?p.translatedNameZh+'（机器参考译名）':placeName(p)):null)||t('planner.'+(event.kind==='REST'?'rest':event.slot==='LUNCH'?(settings.value.interests.includes('FOOD')?'foodLunch':'lunch'):(settings.value.interests.includes('FOOD')?'foodDinner':'dinner')));}
watch([pace,dayIndex],()=>{validationMessage.value='';editFeedback.value='';});
function conflictText(schedule,subject=''){return `${day.value.date} ${subject}: `+schedule.conflicts.map(c=>c==='time'?`${language.value==='zh'?'超出每日结束时间':'Past daily end'} ${schedule.overflow||0} min (${schedule.events.filter(e=>e.end>Number(settings.value.end.slice(0,2))*60+Number(settings.value.end.slice(3))).map(e=>e.place?.name||title(e)).join(' / ')})`:c==='dedicatedDay'?(language.value==='zh'?'大型园区需独立游玩日，请移走其他城市景点':'Large park needs a dedicated day; move other attractions'):c==='parkMeal'?(language.value==='zh'?'外部餐厅与园区活动重叠；请换日期或改为游园结束后用餐，离园再入园规则需核实':'External meal overlaps the park visit. Move it to another day or after the visit; re-entry rules need checking'):c==='openingHours'?`${language.value==='zh'?'开放时间不符':'Outside opening hours'}: ${schedule.events.filter(e=>e.place&&(()=>{const slot=openingSlot(e.place,day.value.date,e.start,e.duration);return slot.status==='closed'||slot.start!==e.start;})()).map(e=>e.place.name).join(' / ')}`:t('planner.conflicts.'+c)).join(' / ')+(language.value==='zh'?'。请减少停留、调整顺序或修改旅行时间。':'. Shorten visits, reorder or change daily hours.');}
function snapshot(){validationMessage.value='';history.value.push(JSON.stringify({variants:variants.value,settings:settings.value}));notice.value='';}
function undo(){validationMessage.value='';editFeedback.value='';const h=history.value.pop();if(h){const data=JSON.parse(h);variants.value=data.variants;settings.value=data.settings;}}
function durationProfile(event){return event.place.visit||visitProfile(event.place);}
const additions=ref(false);watch(()=>props.places.length,(n,o)=>{if(n>o)additions.value=true;});
function replan(){archiveMode.value=false;additions.value=false;snapshot();const preservedDays=Object.fromEntries(current.value.days.filter(d=>d.events.some(e=>Boolean(settings.value.lockedSlots?.[e.id]))).map(d=>[d.date,d]));variants.value=generateItineraries(eligible.value,{...settings.value,preservedDays});}
function toggleLock(id){editTarget.value=id;snapshot();const slots={...settings.value.lockedSlots};if(slots[id])delete slots[id];else{const e=day.value.events.find(e=>e.id===id);slots[id]={date:day.value.date,start:e.start,end:e.end};}settings.value={...settings.value,lockedSlots:slots};editFeedback.value=language.value==='zh'?(slots[id]?'已锁定此景点及时间。':'已解锁。'):(slots[id]?'Place and time locked.':'Unlocked.');}
function edit(event,action,value){
 validationMessage.value='';editFeedback.value='';editTarget.value=event.id;
 if(settings.value.lockedSlots?.[event.id]){validationMessage.value=language.value==='zh'?'请先解锁，再调整此景点。':'Unlock this place before editing.';return;}
 let workingSettings=settings.value;
 const items=day.value.items.map(i=>({...i})),index=items.findIndex(i=>i.place.id===event.id);if(index<0)return;
 if(action==='remove'&&settings.value.mustIds.includes(event.id)&&!window.confirm(language.value==='zh'?'这是必去景点，确认从行程及必去清单删除？':'Remove this must-visit place from the plan and wishlist?'))return;
 if(action==='remove')items.splice(index,1);
 if(['longer','shorter','depth','custom'].includes(action)){
  const profile=event.place.visit||visitProfile(event.place);
  let duration=action==='depth'?profile.range[{quick:0,standard:1,deep:2}[value]]:action==='custom'?Number(prompt(language.value==='zh'?'自定义停留分钟数（15–1440）':'Custom duration in minutes (15–1440)',String(event.duration))):Math.max(15,event.duration+(action==='longer'?15:-15));
  if(!Number.isInteger(duration)||duration<15||duration>1440){editFeedback.value=language.value==='zh'?'未修改：请输入15–1440之间的整数分钟。':'Unchanged: enter whole minutes between 15 and 1440.';return;}
  if(duration<profile.range[0]&&!confirm(language.value==='zh'?`低于该类型建议下限${profile.range[0]}分钟，可能无法体验主要内容。确认短暂停留？`:`Below the suggested minimum of ${profile.range[0]} minutes. Main experiences may be missed. Continue?`))return;
  items[index].duration=duration;
  workingSettings={...settings.value,visitPreferences:{...settings.value.visitPreferences,[event.id]:{minutes:duration,depth:action==='depth'?value:'custom',updatedAt:new Date().toISOString()}}};
 }
 if(action==='up'&&index>0)[items[index-1],items[index]]=[items[index],items[index-1]];
 if(action==='down'&&index<items.length-1)[items[index+1],items[index]]=[items[index],items[index+1]];
 const usedOther=new Set(current.value.days.filter((_,i)=>i!==dayIndex.value).flatMap(d=>d.events.filter(e=>e.place).map(e=>e.place.id)));
 const run=list=>scheduleDay(list,{...workingSettings,planningDate:day.value.date,assignedMeals:day.value.mealAssignments},pace.value,eligible.value.filter(p=>p.category==='FOOD'&&!usedOther.has(p.id)));
 if(action==='replace'){
  if(settings.value.mustIds.includes(event.id)&&!window.confirm(language.value==='zh'?'确认替换此必去景点？替代景点将加入必去清单。':'Replace this must-visit? The replacement will become a must-visit.'))return;
  const used=current.value.days.flatMap(d=>d.events.filter(e=>e.place).map(e=>e.place));
  const options=eligible.value.filter(p=>p.planningEligible!==false&&p.category!=='FOOD'&&!used.some(q=>samePlace(p,q))).sort((a,b)=>(preferenceScore(b,settings.value,[event.place])+(b.category===event.place.category?20:0))-(preferenceScore(a,settings.value,[event.place])+(a.category===event.place.category?20:0)));
  const alternative=options.find(p=>{const trial=items.map((i,n)=>n===index?{place:p}:i);const next=run(trial);return !next.conflicts.length&&preservesLocks(day.value,next,settings.value);});
  if(!alternative){editFeedback.value=language.value==='zh'?'没有符合当前时间和锁定约束的替代景点。':'No replacement fits the current time and locks.';return;}items[index]={place:alternative};
 }
 const schedule=run(items);
 if(schedule.conflicts.length||!preservesLocks(day.value,schedule,settings.value)){validationMessage.value=conflictText({...schedule,conflicts:preservesLocks(day.value,schedule,settings.value)?schedule.conflicts:[...schedule.conflicts,'locked']},title(event));return;}
 snapshot();settings.value=workingSettings;if(action==='replace'&&settings.value.mustIds.includes(event.id))settings.value={...settings.value,mustIds:settings.value.mustIds.map(id=>id===event.id?items[index].place.id:id)};if(action==='remove')settings.value={...settings.value,mustIds:settings.value.mustIds.filter(id=>id!==event.id)};
 Object.assign(day.value,schedule,{userEdited:true,transportReviewed:true});active.value=action==='remove'?'':items[index]?.place.id||'';editFeedback.value=language.value==='zh'?'已更新行程，时间与地图已同步。':'Itinerary, times and map updated.';
}
function select(id){active.value=id;document.getElementById('stop-'+id)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'});}

function exportSnapshot(){return JSON.parse(JSON.stringify({version:1,routeId:routeId.value,destination:props.destination,settings:{...settings.value,pace:pace.value,weather:weatherState.value.data},places:props.places,plan:{...current.value,quality:quality.value},presentation:presentation.value,savedAt:new Date().toISOString()}));}
function persist(){try{saveHistory(exportSnapshot());storageMessage.value=language.value==='zh'?'已保存到本机历史记录。':'Saved to local history.';}catch(e){storageMessage.value=e.message;}}
function changeHotel(hotel){if(!confirm(language.value==='zh'?'更换酒店并重新计算往返路线与行程？原历史快照不会覆盖。':'Change hotel and replan? Original history will remain unchanged.'))return;snapshot();settings.value={...settings.value,hotel,origin:hotel};archiveMode.value=false;const preservedDays=Object.fromEntries(current.value.days.filter(d=>d.events.some(e=>settings.value.lockedSlots?.[e.id])).map(d=>[d.date,d]));variants.value=generateItineraries(eligible.value,{...settings.value,preservedDays});showHotelPicker.value=false;persist();}
function revalidate(){archiveMode.value=false;refreshTransport();}
let autoSaved=false;function saveGenerated(){if(!autoSaved&&!props.restored&&!transportLoading.value){autoSaved=true;persist();}}
watch(transportLoading,saveGenerated);
onMounted(()=>{if(props.restored){presentation.value=props.restored.presentation||{};syncTrafficPaths();}saveGenerated();emit('snapshot',exportSnapshot());});
watch(()=>[current.value,settings.value,presentation.value],()=>emit('snapshot',exportSnapshot()),{deep:true});
defineExpose({exportSnapshot,persist});

</script>
<template><main class="trip-result travel-journal"><button class="text-button back-to-brief" @click="$emit('back')">← {{t('planner.back')}}</button>
<section class="journey-cover"><div class="journey-cover-copy"><span class="section-kicker">YOUR PERSONAL JOURNEY</span><h1><template v-if="language==='zh'"><span class="cover-title-line">{{displayName}}，</span><span class="cover-title-line">{{settings.days===3?'三':settings.days}}日漫游。</span></template><template v-else>{{travelTitle}}</template></h1><p class="cover-dates">{{settings.date}} — {{current.days.at(-1)?.date}} · {{settings.days}} {{language==='zh'?'天':'DAYS'}}</p><p>{{t('planner.parties.'+settings.party)}}<br/>{{settings.interests.map(i=>t('planner.interests.'+i)).join(' / ')}}</p><p class="journey-introduction">{{language==='zh'?'把时间留给喜欢的风景。循着自己的节奏，走进这座城市的日常与故事。':'Make time for the places that move you. Find your own rhythm among the everyday scenes and stories of this city.'}}</p><button class="primary explore-journey" @click="scrollToJourney">{{language==='zh'?'探索我的旅程':'Explore my journey'}} ↗</button></div><JourneyCover :destination="destination"/></section>
<section class="data-notice"><p v-if="archiveMode">{{language==='zh'?'正在查看原始快照；天气、交通与营业信息可能过期。编辑不会覆盖原记录。':'Viewing original snapshot. Weather, transport and hours may be outdated. Edits do not overwrite it.'}} <button @click="revalidate">{{language==='zh'?'按最新信息重新校验':'Revalidate with current information'}}</button></p><p role="status">{{storageMessage}}</p><button class="outline" @click="persist">{{language==='zh'?'保存当前版本到历史':'Save current version to history'}}</button><FavoriteButton type="route" :data="{id:routeId,name:displayName,city:destination.city}" :snapshot="exportSnapshot"/><p v-if="settings.hotel">H · {{settings.hotel.name}} · {{settings.hotel.address}} <FavoriteButton type="hotel" :data="{...settings.hotel,destination}"/></p><button class="text-button" @click="showHotelPicker=!showHotelPicker">{{language==='zh'?'设置 / 修改酒店':'Set / change hotel'}}</button><PlacePicker :resolved-destination="destination" v-if="showHotelPicker" :city="destination.canonicalName||destination.city" kind="hotel" @choose="changeHotel"/><details v-if="current.included?.length"><summary>{{language==='zh'?'景区内游览建议':'Within-site suggestions'}}</summary><p v-for="child in current.included" :key="child.id">{{child.name}} · {{language==='zh'?'已纳入整体游览：':'Included within: '}}{{child.parentName}}</p></details><p v-for="r in current.unplacedRestaurants" :key="r.id">{{r.name}} · {{language==='zh'?r.reason:r.reasonEn}}</p></section><details class="journal-weather"><summary><span>{{displayName}} · {{settings.date}}</span><span v-if="weatherSummary.length">{{t('weather.'+weatherKind(weatherSummary[0].code))}} · {{Math.round(Math.max(...weatherSummary.map(d=>d.high??-100)))}}° / {{Math.round(Math.min(...weatherSummary.map(d=>d.low??100)))}}° <span v-if="weatherAssessment.affected.length"> · {{language==='zh'?'部分时段有天气风险':'Weather risks in some time slots'}}</span></span><span v-else>{{language==='zh'?'预报范围外或天气尚未就绪，展开查看气候参考':'Forecast unavailable or loading; expand for climate reference'}}</span><span>{{language==='zh'?'查看天气详情':'Weather details'}} ＋</span></summary><WeatherPanel v-if="!archiveMode" :destination="destination" :dates="current.days.map(d=>d.date)" @update="weatherState=$event"/><WeatherAdvice v-if="eligible.length&&!archiveMode" :plan="current" :settings="settings" :weather="weatherState" :assessment="weatherAssessment" @apply="applyWeather"/></details>
<section id="journey-route" class="journey-route"><header class="journal-section-heading"><div><span class="section-kicker">YOUR JOURNEY</span><h2>{{language==='zh'?'旅行路线':'Your route'}}</h2></div><div v-if="eligible.length" class="trip-actions"><button class="outline" @click="comparison=!comparison">{{t('planner.compare')}}</button><button class="primary" @click="replan">{{t('planner.replan')}}</button></div></header>
<p v-if="places.some(p=>p.source==='opentripmap')" class="data-notice"><a href="https://opentripmap.com" target="_blank" rel="noopener">OpenTripMap · ODbL</a></p><p v-if="places.some(p=>p.source==='opentripmap')" class="data-notice"><a href="https://opentripmap.com" target="_blank" rel="noopener">OpenTripMap · ODbL</a></p><p class="data-notice" v-if="limited">{{t('planner.snapshot')}}</p><p class="error" v-if="!eligible.length">{{t('planner.empty')}}</p><p class="data-notice" v-if="pending.length">{{t('planner.pending')}} {{pending.join(' / ')}}</p><p class="data-notice" v-if="missing.length">{{t('planner.missingInterest')}} {{missing.map(i=>t('planner.interests.'+i)).join(' / ')}}</p>
<p v-if="places.some(p=>p.source==='openstreetmap')" class="data-notice"><a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap contributors · ODbL</a></p><div class="trip-paces"><button v-for="plan in variants" :key="plan.id" :class="{selected:pace===plan.id}" :aria-pressed="pace===plan.id" @click="pace=plan.id;active=''">{{t('planner.paces.'+plan.id)}}<small>{{t('planner.paceHints.'+plan.id)}}</small></button></div>
<div v-if="comparison" class="comparison-scroll"><table><thead><tr><th>{{t('planner.pace')}}</th><th>{{t('planner.activities')}}</th><th>{{t('planner.fatigue')}}</th><th>{{t('planner.reserve')}}</th></tr></thead><tbody><tr v-for="plan in variants" :key="plan.id"><td>{{t('planner.paces.'+plan.id)}}</td><td>{{plan.days.reduce((s,d)=>s+d.fatigue.activities,0)}}</td><td>{{Math.round(plan.days.reduce((s,d)=>s+d.fatigue.score,0)/plan.days.length)}} / 100</td><td>¥{{plan.days.reduce((s,d)=>s+d.knownCost+d.reserve,0)}}</td></tr></tbody></table></div>
<details v-if="current.unplacedMust.length" class="data-notice" open><summary>{{t('planner.unplaced')}} {{current.unplacedMust.map(nameFor).join(' / ')}}</summary><p v-for="item in current.unplacedDetails" :key="item.id">{{item.name}} · {{item.attempts.map(a=>a.date+': '+a.conflicts.map(c=>c==='capacity'?(language==='zh'?'剩余时段不足，请增加天数或减少其他必去景点':'Insufficient remaining slots; add days or reduce other must-visits'):c==='missingPlace'?(language==='zh'?'地点数据无效，请重新选择':'Invalid place data; select again'):t('planner.conflicts.'+c)).join(', ')+(a.overflow?' +'+a.overflow+' min':'')).join(' / ')}}</p></details>
<nav class="trip-days"><button v-for="(d,i) in current.days" :key="d.day" :aria-pressed="dayIndex===i" :class="{selected:dayIndex===i}" @click="dayIndex=i;active=''">DAY {{String(d.day).padStart(2,'0')}}<small>{{d.date}}</small></button></nav>
<p v-if="dataWarnings.length" class="data-notice" role="status">{{language==='zh'?'部分景点来源不可用；当前使用已取得的真实数据，候选可能不完整。':'Some place sources are unavailable. Available verified data is retained; coverage may be incomplete.'}} {{dataWarnings.join(' / ')}}</p><div class="trip-stats"><div><small>{{t('planner.activities')}}</small><strong>{{day.fatigue.activities}}</strong></div><div><small>{{t('planner.fatigue')}}</small><strong>{{day.fatigue.score}}<small> / 100</small></strong></div><div><small>{{t('planner.stability')}}</small><strong>{{day.fatigue.activities ? day.stability : '—'}}<small> / 100</small></strong></div><div><small>{{t('planner.reserve')}}</small><strong>¥{{day.knownCost+day.reserve}}</strong></div></div>
<p v-if="additions" role="status">{{language==='zh'?'已补充餐饮候选，点击“重新生成”可纳入行程。':'Additional dining options are ready. Regenerate to include them.'}}</p><p class="estimate-note">{{t('planner.estimate')}} {{t('planner.unknownPrice')}}</p>
<details class="estimate-note"><summary>{{language==='zh'?'行程质量与数据可靠性':'Plan quality and data reliability'}}</summary><p>{{language==='zh'?'必去覆盖':'Required coverage'}} {{quality.must.covered}} / {{quality.must.total}} · {{language==='zh'?'总交通':'Total travel'}} {{quality.totalTravel}} min</p><p v-for="q in quality.days" :key="q.date">{{q.date}} · {{language==='zh'?'游览':'Visits'}} {{q.visiting}} min · {{language==='zh'?'交通':'Travel'}} {{q.travel}} min ({{q.travelShare}}%) · {{language==='zh'?'开放时间待核实':'Unverified hours'}} {{q.unknownHours}} · {{language==='zh'?'已查交通 / 估算':'Queried / estimated legs'}} {{q.realLegs}} / {{q.estimatedLegs}} · {{language==='zh'?'真实餐厅 / 用餐预留':'Restaurants / reserved meals'}} {{q.meals.specified+q.meals.recommended}} / {{q.meals.reserved}}</p><p v-for="(issue,i) in quality.issues" :key="i">{{issue.date}} {{issue.name}} · {{language==='zh'?({sparse:'游览较少：现有候选在约束内未能充分补齐，可调整每日时间或添加地点。',longTravel:'通勤较长：请考虑更靠近游览区域的住宿或减少跨区活动。',duplicate:'存在重复景点，需要调整。',constraints:'存在未解决约束，请查看当天原因。',missingMust:'有必去需求未满足，请查看未安排说明。'}[issue.code]):issue.code}}</p><small>{{language==='zh'?'以上为可解释的规划规则检查，不代表景点评分；营业、预约、预报及估算交通仍需核实。':'Rule-based planning checks, not attraction ratings; verify hours, reservations, forecasts and estimated travel.'}}</small></details><details v-if="validationMessage" role="alert" class="edit-validation"><summary>{{language==='zh'?'本次编辑未应用 · 查看原因':'Edit not applied · Details'}}</summary><p>{{validationMessage}}</p></details><p v-if="editFeedback" role="status">{{editFeedback}}</p><details v-if="day.conflicts.length" class="data-notice" role="alert"><summary>{{day.date}} · {{day.conflictOrigin==='transport'?(language==='zh'?'交通更新后需调整':'Adjustment needed after route update'):(language==='zh'?'生成结果需调整':'Generated plan needs adjustment')}} · {{language==='zh'?'查看原因':'Details'}}</summary><p>{{conflictText(day)}}</p></details><details v-if="day.warnings?.some(w=>['walking','fatigue','budget','count'].includes(w.code))" class="estimate-note"><summary>{{language==='zh'?'强度与预算参考提醒':'Effort and budget advisory'}}</summary><p>{{day.warnings.filter(w=>['walking','fatigue','budget','count'].includes(w.code)).map(w=>t('planner.conflicts.'+w.code)).join(' / ')}}</p></details><p class="estimate-note">{{transportLoading?(language==='zh'?'正在核对真实交通时间…':'Checking travel times…'):(language==='zh'?'交通标注为高德查询或估算；无可靠开放时间的地点需出发前确认。预算为人民币规划预留，非实际报价。':'Transport is labelled AMap or estimated. Unknown opening hours need confirmation. Budget is a CNY planning allowance, not a quote.')}}</p><details v-if="day.gaps?.length" class="estimate-note"><summary>{{language==='zh'?'仍有未安排行程的时段 · 查看说明':'Unscheduled time · Details'}}</summary><p>{{day.gaps.map(g=>clock(g.start)+'–'+clock(g.end)).join(' / ')}} · {{language==='zh'?'当前候选未能在交通、开放时间和停留约束内补齐；可添加想去的地点或调整住宿及每日时间。':'Available candidates did not fit the travel, opening-hour and duration constraints. Add preferred places or adjust accommodation and daily hours.'}}</p></details><div class="day-layout"><section class="journey-timeline" :aria-label="language==='zh'?'每日时间线':'Daily timeline'"><div class="timeline-heading"><h3>{{t('planner.day',{n:day.day})}}</h3><button class="text-button" :disabled="!history.length" @click="undo">↶ {{t('planner.undo')}}</button></div><div v-for="event in day.events" :key="event.id" :id="'stop-'+event.id" class="journey-stop" :class="{selected:active===event.id,support:event.kind!=='ACTIVITY'}"><time>{{clock(event.start)}}<small v-if="event.duration">{{clock(event.end)}}</small></time><button v-if="event.place" type="button" class="stop-select" :aria-pressed="active===event.id" @click="active=event.id"><span class="stop-number">{{event.kind==='HOTEL'?'H':String(orderOf(event)).padStart(2,'0')}}</span><span><strong>{{title(event)}}</strong><small><template v-if="event.kind!=='HOTEL'">{{t('planner.stay',{n:event.duration})}}</template><template v-if="event.travel.minutes"> · {{t('planner.travel',{n:event.travel.minutes})}}</template></small><small v-if="event.kind==='MEAL'">{{event.mealType==='specified'?(language==='zh'?'用户指定餐厅':'Your selected restaurant'):(language==='zh'?'附近餐厅推荐 · 营业情况待核实':'Nearby restaurant · verify hours')}}</small><small v-if="eventRisk(event)?.affected">⚠ {{eventRisk(event).reasons.map(r=>t('weatherAdvice.'+r)).join(' / ')}}</small></span></button><div v-else class="support-copy"><strong>{{title(event)}}</strong><small><template v-if="event.kind!=='HOTEL'">{{t('planner.stay',{n:event.duration})}}</template><template v-if="event.travel.minutes"> · {{t('planner.travel',{n:event.travel.minutes})}}</template></small><small v-if="event.foodCandidate?.near?.name">{{language==='zh'?'用餐范围：':'Dining area: '}}{{event.foodCandidate.near.name}}{{language==='zh'?'附近':''}}</small></div><ActivityImage v-if="event.place&&event.kind!=='HOTEL'" :place="present(event.place)" @retry="enrichDay(true,event.place.id,'photo')" @unavailable="recoverPhoto(event.place)"/></div></section><aside><UnifiedTripMap :key="destination.id+day.day" :destination="destination" :places="mapPlaces" :itinerary-route="transportPlaces" :active="active" :route-paths="routePaths" @select="select"/><p>{{t('planner.free',{n:day.free})}} · {{t('planner.estimatedWalking',{n:day.fatigue.walking})}} · {{t('planner.travel',{n:day.fatigue.travel})}}</p><TripTransport v-if="!archiveMode" @routes="acceptTransport" :initial-mode="settings.transport||'transit'" :places="transportPlaces" :destination="destination" @paths="$event.length&&(routePaths=$event)"/></aside></div></section><section class="journal-places"><header class="journal-section-heading"><div><span class="section-kicker">PLACES ALONG THE WAY</span><h2>{{language==='zh'?'沿途风景':'Places along the way'}}</h2></div><span>DAY {{String(day.day).padStart(2,'0')}}</span></header><section class="daily-timeline"><div class="timeline-heading"><h2>{{t('planner.day',{n:day.day})}}</h2><button class="text-button" :disabled="!history.length" @click="undo">↶ {{t('planner.undo')}}</button></div><p v-if="notice" role="status">{{t(notice)}}</p><p v-if="day.fatigue.activities<2&&!day.items.some(i=>i.place.visit?.fullDay)" class="data-notice">{{t('planner.limited')}}</p><p v-if="!mealWindows(settings).length" class="data-notice">{{t('planner.noMealWindow')}}</p>
<article v-for="event in photoEvents" :key="event.id" :id="'event-'+event.id" class="trip-event" :class="{selected:active===event.id,'support-event':event.kind!=='ACTIVITY'}"><p class="event-time">{{clock(event.start)}} — {{clock(event.end)}}<span>{{t('planner.stay',{n:event.duration})}}</span></p><div class="event-body" @click="event.place&&(active=event.id)"><ActivityImage v-if="event.place&&event.kind!=='HOTEL'" :place="present(event.place)" @retry="enrichDay(true,event.place.id,'photo')" @unavailable="recoverPhoto(event.place)"/><div><small class="place-index">{{String(orderOf(event)).padStart(2,'0')}} / {{event.place?.visit?(language==='zh'?event.place.visit.label:event.place.visit.en):t('planner.types.'+event.activityType)}}</small><h3>{{title(event)}}</h3><p v-if="event.place && title(event)!==event.place.name" class="original-name">{{event.place.name}}</p><small v-if="day.warnings?.some(w=>w.id===event.place?.id&&w.code==='unknownHours')">{{language==='zh'?'开放时间待确认':'Opening hours need confirmation'}}</small><p v-if="event.place?.address">{{event.place.address}}</p><a v-if="safeWebsite(event.place?.website)" :href="safeWebsite(event.place.website)" target="_blank" rel="noopener noreferrer" @click.stop>{{t('global.website')}} ↗</a><p v-if="event.place && present(event.place).photoStatus==='loading'">{{t('planner.loadingMedia')}}</p><button v-if="event.place && ['error','missing'].includes(present(event.place).photoStatus)" class="text-button" @click.stop="enrichDay">{{t('planner.retryMedia')}}</button><p v-if="event.place && title(event)!==event.place.name" class="original-name">{{event.place.name}}</p><small v-if="day.warnings?.some(w=>w.id===event.place?.id&&w.code==='unknownHours')">{{language==='zh'?'开放时间待确认':'Opening hours need confirmation'}}</small><p v-if="event.place?.address">{{event.place.address}}</p><a v-if="safeWebsite(present(event.place)?.website)" :href="safeWebsite(present(event.place)?.website)" target="_blank" rel="noopener noreferrer" @click.stop>{{t('global.website')}} ↗</a><button v-if="event.place && ['error','missing'].includes(present(event.place).photoStatus)" class="text-button" @click.stop="enrichDay(true,event.place.id)">{{t('planner.retryMedia')}}</button><FavoriteButton v-if="event.place" :type="event.kind==='MEAL'?'restaurant':'attraction'" :data="{...present(event.place),destination}"/><TouristReviews v-if="event.place" :place="present(event.place)" :destination="destination"/><PlaceDescription v-if="event.place" :place="present(event.place)"/><p v-if="present(event.place)?.description">{{present(event.place).description}}</p><p>{{reason(event)}}</p><details v-if="event.kind==='ACTIVITY'" class="duration-reference"><summary>{{language==='zh'?'游览时间参考（估算）':'Visit duration (estimate)'}} · {{language==='zh'?durationProfile(event).label:durationProfile(event).en}}</summary><p>{{durationProfile(event).range[0]}}–{{durationProfile(event).range[2]}} min · {{language==='zh'?'按游览范围估算，不是官方规定时长；排队、内部交通及开放情况需核实。':'Estimated scope, not official duration; verify queues, internal travel and opening information.'}}</p><p v-if="event.internalBreaks">{{language==='zh'?'已包含现场简餐、休息与内部移动预留；不重复插入城市午餐，用餐设施需另行确认。':'Includes on-site meal, rest and internal travel allowances.'}}</p><p v-if="parentProfile(event.place)">{{language==='zh'?'可能属于大型园区内项目；请核实入园门票、预约和交通条件。':'Likely an attraction inside a larger site; verify park admission, reservations and access.'}}</p><a v-for="url in durationProfile(event).sources" :key="url" :href="url" target="_blank" rel="noopener">{{language==='zh'?'资料来源（核验类型与活动）':'Source (type and activities)'}} ↗</a><small v-if="durationProfile(event).reviewedAt"> · {{durationProfile(event).reviewedAt}}</small></details><p v-if="eventRisk(event)?.affected" class="event-weather-risk" role="note">⚠ {{eventRisk(event).reasons.map(r=>t('weatherAdvice.'+r)).join(' / ')}}<span v-if="eventRisk(event).environment==='unknown'"> · {{t('weatherAdvice.unknown')}}</span></p><p v-if="event.travel.minutes"><small>{{event.travel.estimated?(language==='zh'?'估算':'Estimated'):'AMap'}} · {{event.travel.mode}}</small> ↳ {{t('planner.travel',{n:event.travel.minutes})}}</p><small v-if="event.kind==='MEAL'&&!event.place">{{t('planner.unmatchedFood')}}</small></div></div><div v-if="event.kind==='ACTIVITY'" class="event-controls"><label>{{language==='zh'?'游览深度':'Visit depth'}} <select :value="settings.visitPreferences?.[event.id]?.depth||'standard'" @change="edit(event,'depth',$event.target.value);$event.target.value=settings.visitPreferences?.[event.id]?.depth||'standard'"><option value="quick">{{language==='zh'?'快速参观':'Quick'}}</option><option value="standard">{{language==='zh'?'常规游览':'Standard'}}</option><option value="deep">{{language==='zh'?'深度体验':'In depth'}}</option><option v-if="settings.visitPreferences?.[event.id]?.depth==='custom'" value="custom" disabled>{{language==='zh'?'自定义':'Custom'}}</option></select></label><button class="text-button" @click="edit(event,'custom')">{{language==='zh'?'自定义时长':'Custom duration'}}</button><button class="outline" :disabled="event.duration<=15" :title="event.duration<=15?(language==='zh'?'最短停留15分钟':'Minimum stay: 15 minutes'):''" @click="edit(event,'shorter')">−15</button><button class="outline" @click="edit(event,'longer')">+15</button><button class="text-button" :disabled="day.items[0]?.place.id===event.id" :title="day.items[0]?.place.id===event.id?(language==='zh'?'已经是第一个景点':'Already the first stop'):''" @click="edit(event,'up')">{{t('planner.up')}}</button><button class="text-button" :disabled="day.items.at(-1)?.place.id===event.id" :title="day.items.at(-1)?.place.id===event.id?(language==='zh'?'已经是最后一个景点':'Already the last stop'):''" @click="edit(event,'down')">{{t('planner.down')}}</button><button class="text-button" :disabled="Boolean(settings.lockedSlots?.[event.id])" :title="settings.lockedSlots?.[event.id]?(language==='zh'?'请先解锁':'Unlock first'):''" @click="edit(event,'replace')">{{t('planner.replace')}}</button><button class="text-button" @click="toggleLock(event.id)">{{t(settings.lockedSlots?.[event.id]?'planner.unlock':'planner.lock')}}</button><button class="text-button" :disabled="Boolean(settings.lockedSlots?.[event.id])" :title="settings.lockedSlots?.[event.id]?(language==='zh'?'请先解锁':'Unlock first'):''" @click="edit(event,'remove')">{{t('planner.remove')}}</button></div><p v-if="editTarget===event.id && (validationMessage||editFeedback)" role="status" class="estimate-note">{{validationMessage||editFeedback}}</p></article>
